{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss combines advantage signals with cost gap to prioritize pairs where the advantage difference aligns with cost difference, encouraging the model to prefer options with lower cost and higher advantage. It uses logsigmoid to smoothly approximate the probability of superiority and penalizes mismatches, leading to better preference calibration.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l) * (cost_gap))",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage_cost",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "mean", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch['cost_gap']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    advantage_diff = ops.sub(advantage_w, advantage_l)\n    pairwise_score = ops.logsigmoid(advantage_diff)\n    weighted_score = ops.mul(pairwise_score, cost_gap)\n    return ops.mean(weighted_score)"
}

{
  "name": "loss_logsigmoid_001_cost_sum_aggregation",
  "intuition": "pairwise logsigmoid loss with shifted aggregation from mean to sum for stronger gradient signal",
  "pseudocode": "loss = sum(-logsigmoid(clamp(alpha*scale*(log_prob_w - log_prob_l) - 0.1*(cost_b - cost_a), -20, 20)) * weight)",
  "hyperparams": {
    "scale": 1.9496803035382082,
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "sum",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    x = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.sum()"
}

{
  "name": "pairwise_advantage_loss",
  "intuition": "This loss emphasizes the advantage signals (advantage_w, advantage_l) by encouraging the model to prioritize pairs where the advantage indicates better preferred samples, promoting preference consistency. Using the advantage signals directly provides a stable and informative gradient signal for RL in CO tasks.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l + bias))",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": "none"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    bias = extra.get('bias', 0.0)\n    diff = ops.sub(advantage_w, advantage_l)\n    pairwise_signal = ops.add(diff, bias)\n    loss = ops.mean(ops.logsigmoid(pairwise_signal))\n    return ops.neg(loss)"
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss emphasizes preferencing pairs where the advantage signals (indicating preference strength) align with the cost_gap difference. By weighting advantage signals with the exponential of the cost_gap, it promotes selecting pairs with more significant advantage aligned with larger cost gap. Using logsigmoid on advantage signals encourages smooth, stable gradients, and the pairwise formulation directly relates advantage differences to the cost gap, promoting better preference learning.",
  "pseudocode": "adv_w = advantage_w; adv_l = advantage_l; gap = cost_gap; loss = mean(logsigmoid(adv_w - adv_l) * exp(gap))",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage",
    "link_family": "exponential",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "exp"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    gap = batch['cost_gap']\n    weight = batch['weight']\n    # Compute pairwise advantage difference\n    adv_diff = adv_w - adv_l\n    # Apply logsigmoid for smooth ranking\n    sigm_diff = ops.logsigmoid(adv_diff)\n    # Exponentiate cost_gap for weighting\n    exp_gap = ops.exp(gap)\n    # Weighted mean to aggregate\n    loss = ops.sum(sigm_diff * exp_gap) / ops.count(sigm_diff)\n    return loss"
}

{
  "name": "pairwise_advantage_zscore_margin",
  "intuition": "This loss computes the normalized advantage difference between pairs using z-score normalization, then applies a hinge at a specified margin to enforce a clear margin between preferred and less preferred options. By focusing on advantage differences directly, it encourages the model to increase the advantage gap beyond the margin, which aligns with preference ranking objectives while maintaining scale invariance.",
  "pseudocode": "advantage_diff = advantage_w - advantage_l\nadvantage_norm = zscore(advantage_diff)\nmargin = hyperparam_margin\nloss_per_pair = relu(margin - advantage_norm)\nweighted_loss = loss_per_pair * weight\nfinal_loss = mean(weighted_loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_hinge",
    "signal_family": "advantage_gap",
    "link_family": "relu",
    "agg_family": "mean",
    "constraint_family": "zscore_normalization"
  },
  "operators_used": ["relu", "zscore", "mean", "sub", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    margin = float(extra.get('margin', extra.get('hyperparams', {}).get('margin', 1.0)))\n    gap = ops.sub(advantage_w, advantage_l)\n    gap_norm = ops.zscore(gap)\n    loss_per_pair = ops.relu(ops.sub(margin, gap_norm))\n    if weight is not None:\n        loss_per_pair = ops.mul(loss_per_pair, weight)\n    return ops.mean(loss_per_pair)"
}

{
