  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    margin = float(extra.get('margin', extra.get('hyperparams', {}).get('margin', 1.0)))\n    gap = ops.sub(advantage_w, advantage_l)\n    gap_z = ops.zscore(gap)\n    loss_pairs = ops.relu(ops.sub(margin, gap_z))\n    if weight is not None:\n        loss_pairs = ops.mul(loss_pairs, weight)\n    return ops.mean(loss_pairs)"
